WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY amount DESC, id) AS dedup_rank FROM orders QUALIFY dedup_rank = 1), latest_match AS (SELECT s.id, s.customer_id, s.store_id, s.order_date, s.status, s.amount, s.shipping_fee, s.dedup_rank, top1.carrier, top1.shipment_status FROM deduped s LEFT JOIN LATERAL (SELECT c.carrier, c.status AS shipment_status FROM shipments c WHERE c.order_id = s.id ORDER BY c.delivered_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), deduped_orders AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY shipment_status ORDER BY order_date DESC, id) AS dedup_rank_2 FROM latest_match) ranked WHERE dedup_rank_2 = 1), valid AS (SELECT id, customer_id, order_date, status, amount, shipping_fee, dedup_rank, carrier, COALESCE(shipping_fee, 0) AS shipping_fee_filled, CASE WHEN carrier IN ('Kerry', 'UPS') THEN 'Group A' ELSE 'Other' END AS carrier_group, COALESCE(shipment_status, 'UNKNOWN') AS resolved_shipment_status FROM deduped_orders WHERE order_date > DATE '2023-07-19' AND shipment_status IS NOT NULL) SELECT CASE WHEN shipping_fee >= 30 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(status)) AS num_status, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM valid GROUP BY shipping_fee_tier ORDER BY shipping_fee_tier NULLS FIRST;
